cards.solution:
import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.bulkhead.*;
import io.github.resilience4j.ratelimiter.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int batas = Integer.parseInt(in.nextLine());
        RateLimiter limiter = RateLimiter.of("api", RateLimiterConfig.custom()
                .limitForPeriod(batas)
                .limitRefreshPeriod(Duration.ofSeconds(60))
                .timeoutDuration(Duration.ZERO)
                .build());
        int nomor = 1;
        while (in.hasNextLine()) {
            String pengguna = in.nextLine();
            String hasil = limiter.acquirePermission() ? "diproses" : "429 terlalu banyak permintaan";
            System.out.println(nomor++ + ". " + pengguna + ": " + hasil);
        }
    }
}
